pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: residual space remaining after placing the item
    let mut score = post_residual as f64;

    // 1. Penalize dead space that cannot hold the next item
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // 2. Penalize residuals smaller than the average (wasteful gaps)
    if (post_residual as f64) < mean_residual {
        score += 0.8 * (mean_residual - post_residual as f64);
    }

    // 3. Reward when this is the last fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // 4. Strong reward for closing a bin (perfect fit)
    if post_residual == 0 {
        score -= 120.0;
    }

    // 5. New‑bin penalty, softened if the next item is very large
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let factor = if next_item_size as f64 > 0.9 * bin_capacity as f64 {
            5.0
        } else {
            20.0
        };
        score += factor;
    }

    // 6. Encourage using many open bins (mildly reward more open bins)
    if open_bins_count > 8 {
        score -= 1.0 * (open_bins_count as f64).sqrt();
    }

    // 7. Near the end of the stream, be aggressive about closing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.97 {
        score -= 15.0;
    }

    // 8. Small bonus for a highly full bin when many bins are open
    if bin_residual < bin_capacity / 5 && open_bins_count > 0 {
        score -= 6.0;
    }

    // 9. Extra incentive for extremely tight packing
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    if residual_ratio < 0.15 && open_bins_count > 0 {
        score -= 4.0;
    }

    // 10. Penalty for bins with too much space when many are open
    if open_bins_count > 10 && residual_ratio > 0.7 {
        score += 10.0;
    }

    // 11. Look‑ahead: penalize if the next item is larger than the residual
    if next_item_size > 0 && next_item_size as f64 > residual_ratio * bin_capacity as f64 {
        score += 5.0;
    }

    // 12. Minor bonus for very few items left
    let remaining = total_items - step_index;
    if remaining < 10 {
        score -= 5.0;
    }

    score
}

